head.script:
// 테스트 설명, 유효성 값 설정
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (설정 영역 con 옵션 미생성)
//  - description 첫 문장과 propval 첫 문장은 같은 내용이므로 propval 값 조건(Column ID 설정 시)을 붙여 1개 항목으로 작성
scwin.tData = {
    "description" : "[column > P > depthColumn]<br/>inputType='drilldown' 인 Column 에서 각 Row 의 계층 깊이 값을 갖는 Column 의 ID 를 설정합니다.",
    "validation" : [
        "Column ID 설정 시, 각 Row 의 계층 깊이 값을 갖는 Column 의 ID 를 설정합니다.",
        "계층 깊이 값은 정수로 해석할 수 있는 값이어야 하며, 정수로 해석할 수 없는 값은 Row 에 들여쓰기가 적용되지 않고 하위 Row 가 없는것으로 처리됩니다.",
        "계층 깊이 값은 depthStartIndex 속성값을 최상위로 처리하여 들여쓰기를 계산하며, '0' 부터 시작하는 데이터를 사용하려면 Column 의 depthStartIndex 를 '0' 으로 설정합니다.",
        "계층 구조는 Row 의 순서와 계층 깊이 값만으로 판정되므로, 부모 Row 바로 뒤에 자식 Row 가 오도록 데이터가 정렬되어야 합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (depthColumn=depth, depthStartIndex 미설정)
    con_depthColumn.setValue("depth");
    con_depthStartIndex.setSelectedIndex(0);

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 조직 데이터 (8건) - 같은 Row 에 계층 깊이 값 Column 3종을 둔다
//  - depth     : 1 부터 시작하는 계층 깊이 값 (1 ~ 3)
//  - depth0    : 0 부터 시작하는 계층 깊이 값 (depth - 1)
//  - depthText : depth 와 같되 영업본부 = a, 재무팀 = 빈값 (정수로 해석할 수 없는 값)
scwin.rowSorted = [
    { "name" : "본사", "depth" : "1", "depth0" : "0", "depthText" : "1" },
    { "name" : "경영지원본부", "depth" : "2", "depth0" : "1", "depthText" : "2" },
    { "name" : "인사팀", "depth" : "3", "depth0" : "2", "depthText" : "3" },
    { "name" : "재무팀", "depth" : "3", "depth0" : "2", "depthText" : "" },
    { "name" : "영업본부", "depth" : "2", "depth0" : "1", "depthText" : "a" },
    { "name" : "영업1팀", "depth" : "3", "depth0" : "2", "depthText" : "3" },
    { "name" : "연구소", "depth" : "1", "depth0" : "0", "depthText" : "1" },
    { "name" : "개발센터", "depth" : "2", "depth0" : "1", "depthText" : "2" }
];

// 정렬되지 않은 데이터 : 경영지원본부의 자식 (인사팀, 재무팀) 을 맨 뒤 (개발센터 다음) 로 옮김
scwin.rowUnsorted = [
    scwin.rowSorted[0], scwin.rowSorted[1], scwin.rowSorted[4], scwin.rowSorted[5],
    scwin.rowSorted[6], scwin.rowSorted[7], scwin.rowSorted[2], scwin.rowSorted[3]
];



// comp 생성
//  - name : 검증 대상 Body Column (inputType=drilldown, depthColumn = con_depthColumn, depthStartIndex = con_depthStartIndex)
//  - depth / depth0 / depthText : 계층 깊이 값 표시용 Column
//  - showDepth 는 설정하지 않음 (데이터 로딩 시 전체 Row 펼침)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 조직명 Column 에 inputType=drilldown 적용, 계층 깊이 값 Column 은 depth (1 부터), depth0 (0 부터), depthText (영업본부 = a, 재무팀 = 빈값)\n[확인] (계층 상태 확인) 버튼으로 Row 별 깊이 값 / 들여쓰기(px) / 하위 Row / 표시 여부 확인\n[순서] (정렬되지 않은 데이터 로딩) 은 인사팀, 재무팀을 맨 뒤로 옮긴 데이터 -> 경영지원본부, 개발센터의 펼침/접힘 아이콘 클릭 후 확인"', '', 'label1');

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let properties = {
        depthColumn : con_depthColumn.getValue(),
        depthStartIndex : con_depthStartIndex.getValue()
    };
    let cList = $c.gcm.createCList(properties);

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 dataList (계층 깊이 값은 빈값/문자 보존을 위해 text)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="조직명" dataType="text"></w2:column>';
    strDlt += '<w2:column id="depth" name="depth" dataType="text"></w2:column>';
    strDlt += '<w2:column id="depth0" name="depth0" dataType="text"></w2:column>';
    strDlt += '<w2:column id="depthText" name="depthText" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON(scwin.rowSorted, false);

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:520px;height:400px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="220" style="" inputType="text" id="column1" value="조직명 (drilldown)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column2" value="depth"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column3" value="depth0"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="depthText"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="220" style="text-align:left;" inputType="drilldown" id="name" value="" ' + cList + '></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="depth" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="depth0" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="depthText" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// validation 1, 2, 3, 4 판정 출력 : 전체 데이터 Row 의 조직명 / 깊이 값 / 들여쓰기 / 하위 Row / 표시 여부
//  - 표시 여부 : 화면 표시 Row(getDataLength) 를 getRealRowIndex 로 데이터 Row 인덱스로 바꿔 포함되면 표시, 없으면 숨김 (접힘)
//  - 들여쓰기 : 조직명 Cell 왼쪽 경계부터 펼침/접힘 아이콘까지의 거리(px)
//  - 하위 Row : 아이콘 class (w2grid_minus = 있음(펼침), w2grid_plus = 있음(접힘), w2grid_leaf = 없음)
scwin.btn_checkStatus_onclick = function () {
    let depthColumn = con_depthColumn.getValue();
    let shown = {};
    let displayLength = target1.getDataLength();
    for (let i = 0; i < displayLength; i++) {
        shown[target1.getRealRowIndex(i)] = i;
    }
    let arrAll = dlt_bind.getAllJSON();
    let totalRow = target1.getTotalRow();
    for (let r = 0; r < totalRow; r++) {
        let str = "Row " + r + " '" + arrAll[r].name + "'";
        if (depthColumn !== "") {
            str += " / 깊이 값 : '" + arrAll[r][depthColumn] + "'";
        }
        if (shown[r] === undefined) {
            wf_body_bottom.getObj("scwin").setReturnValue(str + " / 숨김");
            continue;
        }
        let td = document.querySelector("#" + target1.id + " td[id$='_cell_" + shown[r] + "_0']");
        let icon = td ? td.querySelector(".w2grid_minus, .w2grid_plus, .w2grid_leaf") : null;
        if (icon) {
            let indent = Math.round(icon.getBoundingClientRect().left - td.getBoundingClientRect().left);
            let child = icon.classList.contains("w2grid_minus") ? "있음(펼침)" : (icon.classList.contains("w2grid_plus") ? "있음(접힘)" : "없음");
            str += " / 들여쓰기 : " + indent + "px / 하위 Row : " + child;
        } else {
            str += " / 펼침/접힘 아이콘 없음";
        }
        wf_body_bottom.getObj("scwin").setReturnValue(str + " / 표시");
    }
}



// validation 4 : 정렬된 데이터 (부모 Row 바로 뒤에 자식 Row) 로딩
scwin.btn_loadSorted_onclick = function () {
    dlt_bind.setJSON(scwin.rowSorted, false);
}



// validation 4 : 정렬되지 않은 데이터 (경영지원본부의 자식 Row 를 맨 뒤로 옮김) 로딩
scwin.btn_loadUnsorted_onclick = function () {
    dlt_bind.setJSON(scwin.rowUnsorted, false);
}
